 n={"paper_id":pid,"title":p["title"],"theme_id":theme,"subtheme_id":sub,"concept_id":concept,"bp":bp,"wh":wh,"naive":naive,"ap":ap,"mech":mech,"math":math,"eval":ev,"ww":ww,"po":"The paper's payoff is a more explicit account of "+concept+"; the reported benefit remains author-reported.","limits":lim,"dots":{"theme_id":theme,"subtheme_id":sub,"concept_id":concept,"sibling_family":"batch-062"},"source":{"kind":"official-isca-archive-paper-page-plus-captured-pdf-text","pdf_sha256":ph,"full_text_sha256":th,"pdf_path":"data/interspeech-2025-pdfs/"+pid+".pdf","text_path":"data/interspeech-2025-text/"+pid+".txt"},"depth":"D3","evidence_boundary":"D3 structured analyst note backed by captured PDF/text; result remains author-reported and was not independently reproduced."}
 notes.append(n); papers.append({"paper_id":pid,"title":p["title"],"paper_url":p["paper_url"],"pdf_url":p["pdf_url"],"abstract":p.get("abstract",""),"pdf_sha256":ph,"full_text_sha256":th,"full_text_path":"data/interspeech-2025-text/"+pid+".txt","evidence_depth":"D3"}); sem.append({"paper_id":pid,"title":p["title"],"decision":"supported","confidence":"analyst-reviewed-D3","theme_id":theme,"subtheme_id":sub,"concept_id":concept,"semantic_reasoning":"Captured full paper supports "+concept+" under "+sub+"; author-reported result and limits are preserved.","evidence_depth":"D3","review_state":"analyst-reviewed","claim_boundary":"Captured official PDF supports the structured D3 note; independent reproduction is not established."}); claims.append({"claim_id":"IS25-D3C62-%02d"%i,"paper_id":pid,"subtheme":sub,"claim":ww,"evidence_depth":"D3","pdf_sha256":ph,"full_text_sha256":th,"support_status":"paper-reported-not-independently-verified","independent_support_status":"not-established","limitations":lim}); md += ["## %d. %s"%(i,sub),"","**Paper:** [%s](%s)"%(p["title"],p["paper_url"]),"**Evidence:** D3; PDF SHA-256 %s; full text captured." ,""]+["- **%s:** %s"%(label,n[key]) for key,label in [("bp","Ordinary problem"),("wh","Why hard"),("naive","Naive attempt"),("ap","Central move"),("mech","Mechanism"),("math","Mathematical/conceptual structure"),("eval","Evaluation"),("ww","What paper reports"),("limits","Limits")]]+[""]
