(DATA/"interspeech-2025-sixtysecond-d3-papers.json").write_text(json.dumps({"venue":"INTERSPEECH 2025","batch_id":"interspeech-2025-d3-batch-062","papers":papers},indent=2,ensure_ascii=False)+"\n")
